theme.stylesheet:
/*
 * Auto dark mode for the FusionAuth hosted pages (fusionauth-app 1.68).
 * The hosted templates carry no .card/.panel classes; every color is painted
 * through theme CSS variables, so dark mode is just re-pointing those
 * variables. Light mode is left entirely to the theme defaults.
 * NOTE: this CSS is duplicated in scripts/local-stack/kickstart.json and
 * containers/fusionAuth/kickstart.json - keep both copies in sync.
 */
@media (prefers-color-scheme: dark) {
  :root {
    /* Admin-configurable source variables consumed by fusionauth-hosted.css */
    --page-background: #121212;
    --panel-background: #1e1e1e;
    --font-color: #e0e0e0;
    --input-background: #2a2a2a;
    --input-text: #f1f5f9;
    --link-color: #38bdf8;
    --link-color-focus: #7dd3fc;

    /* Derived internals whose auto-computed value doesn't suit dark mode */
    --color-panel-border: #333333;
    --color-input-placeholder: #94a3b8;
  }
}
